<?php
namespace qqworld_collector\module\collect_filter; require_once dirname(__DIR__) . '/security-boundaries.php'; class wp_filter extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (is_string($args) && !empty($args)) { $tag_names = explode("\r\n", $args); foreach ($tag_names as $tag_name) { $tag_name = trim($tag_name); $filepath = \qqworld_collector\security\local_content_filter_path(__DIR__ . DIRECTORY_SEPARATOR . 'wp_filter', $tag_name); if ($filepath === false) continue; if (!has_filter($tag_name)) require_once $filepath; $item = apply_filters($tag_name, $item, $source_link, $html, $type, $item_args, $download_args); } } return $item; } } ?>